/*
 * A032708  Numbers k such that k prefixed by '8' and followed by '1' is
 *          prime.
 * https://oeis.org/A032708
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n-th integer k such that the decimal number formed by
 *            * concatenating 8, k, and 1 (i.e., 8·10^(d+1)+k·10+1) is prime,
 *            * where d = number of decimal digits of k. The sequence is
 *            generated by a * simple search over successive k. All
 *            computations are performed in seq_t * to preserve exact...
 * Range:     u8 n <= 2, u16 n <= 28, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   digits, ensure_capacity, isPrimeGeneric, pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/digits.h"
#include "../utils/pow10.h"
#include "../utils/isPrimeGeneric.h"
#include "../utils/ensure_capacity.h"

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;
    static size_t cache_size = 0;
    static size_t cache_cap   = 0;
    static idx_t next_k = 1;        /* next k to test */

    /* Generate more terms until we have at least n of them. */
    while (cache_size < (size_t)n) {
        idx_t k = next_k;
        /* Build the number 8·10^(digits(k)+1) + k·10 + 1 */
        idx_t d = digits(k);
        seq_t num = 8 * pow10(d + 1) + (seq_t)k * 10 + 1;
        if (isPrimeGeneric(num)) {
            /* Grow the cache if necessary. */
            ensure_capacity(cache_size + 1, &cache_cap,
                            (void **)&cache, sizeof(seq_t));
            cache[cache_size++] = (seq_t)k;
        }
        ++next_k;
    }

    return cache[(size_t)n - 1];
}
